   if not hint.active:hint.remaining=maxf(0.0,(int(entry.activate)-now)*.001)
  if entry.kind=="nest" or entry.kind=="bloom_spores":
   hint.lair="memory" if entry.kind=="bloom_spores" else "nursery"
   if not hint.active:hint.remaining=maxf(0.0,(int(entry.activate)-now)*.001)
